<?php
require_once __DIR__.'/includes/bootstrap.php'; require_login();
$u=current_user(); $id=(int)($_GET['id']??$_POST['service_id']??0); $error='';$notice='';$domain=null;
if($db){$st=$db->prepare('SELECT cs.*,ds.registrar_name FROM customer_services cs JOIN domain_services ds ON ds.customer_service_id=cs.id WHERE cs.id=? AND cs.user_id=? AND cs.service_type="domain" LIMIT 1');$st->execute([$id,$u['id']]);$domain=$st->fetch();}
if(!$domain){http_response_code(404);exit('Domain not found.');}
if(is_post()){verify_csrf();public_form_guard($db, 'domain_transfer', $_POST['recaptcha_token'] ?? '');$note=trim($_POST['note']??'');try{$st=$db->prepare("SELECT id,status FROM domain_transfer_requests WHERE customer_service_id=? AND status IN ('requested','in_progress') ORDER BY id DESC LIMIT 1");$st->execute([$id]);if($st->fetch())throw new RuntimeException('A transfer request is already open for this domain.');$db->beginTransaction();$db->prepare('INSERT INTO domain_transfer_requests(customer_service_id,user_id,status,note) VALUES(?,?,?,?,?)')->execute([$id,$u['id'],'requested',$note?:null]);$ticket=make_ticket_number($db);$db->prepare('INSERT INTO support_tickets(ticket_number,user_id,service_id,category,priority,subject,status) VALUES(?,?,?,?,?,?,?)')->execute([$ticket,$u['id'],$id,'domain','normal','Domain transfer assistance: '.$domain['domain_name'],'open']);$tid=(int)$db->lastInsertId();$db->prepare('INSERT INTO support_ticket_messages(ticket_id,sender_user_id,sender_role,message) VALUES(?,?,?,?,?)')->execute([$tid,$u['id'],'client','I would like assistance transferring my domain '.$domain['domain_name'].($note?"\n\n".$note:'')]);$db->commit();$adminEmail=support_admin_email($db);wdh_queue_email($db,$adminEmail,'Domain transfer request '.$ticket,'A customer has requested transfer assistance for '.$domain['domain_name'].'. Ticket: '.$ticket,'ticket',null,null,$id);$notice='Your transfer assistance request has been submitted. Ticket '.$ticket.'.';}catch(Throwable $e){if($db&&$db->inTransaction())$db->rollBack();$error=$e->getMessage();}}
?><!doctype html><html lang="<?=e($LANG)?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Transfer Domain — WDH</title><link rel="stylesheet" href="assets/css/style.css?v=wdh-ui-v8"><link rel="stylesheet" href="assets/css/catalog.css?v=wdh-ui-v8"></head><body><?php require __DIR__.'/includes/header.php';?><main class="portal-page"><div class="breadcrumbs">Home › Client Portal › Domain Transfer</div><div class="portal-welcome"><div><span class="eyebrow mint">TRANSFER SUPPORT</span><h1><?=e($domain['domain_name'])?></h1><p>Request help preparing your domain transfer.</p></div></div><?php if($notice):?><div class="alert success-alert"><?=e($notice)?></div><?php endif;?><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><section class="cart-card" style="max-width:760px"><div class="security-note">For security, your EPP/Auth code is only shown inside your signed-in account. You can request assistance here and WDH will guide you through the transfer process.</div><form method="post"><?=csrf_field()?><input type="text" name="website" value="" class="hp-field" tabindex="-1" autocomplete="off" aria-hidden="true"><?=recaptcha_field('domain_transfer')?><input type="hidden" name="service_id" value="<?=$id?>"><label>What do you need help with?<textarea name="note" rows="6" placeholder="Tell us the registrar you are transferring to and any special instructions."></textarea></label><button class="btn primary">Submit Transfer Request →</button></form></section></main><?php require __DIR__.'/includes/footer.php';?></body></html>
